import { Injectable } from '@angular/core';
import { Observable, Subscriber, catchError, defer, map, of, throwError, timer } from 'rxjs';

import { AppModeService } from './app-mode.service';

/** One pushed result of a subscribed GET: what the HTTP request would have returned. */
export interface LiveEvent {
  status: number;
  body: string;
}

/** Thrown to subscribers when the socket cannot be used, so they go back to polling. */
export class LiveUnavailableError extends Error {
  constructor() {
    super('live socket unavailable');
  }
}

interface LiveSub {
  path: string;
  everyMs: number;
  subscriber: Subscriber<LiveEvent>;
}

// After this many failed attempts without ever opening, the socket is given up on.
const maxFailedOpens = 2;

/**
 * Subscriptions over the hypervisor's /ws socket (pkg/visor/hypervisor_ws.go).
 * The hypervisor re-runs a subscribed GET on an interval and pushes the result
 * only when it changed, so pages stop polling over HTTP. One socket serves the
 * whole UI; it reconnects and resubscribes after a drop.
 */
@Injectable({
  providedIn: 'root'
})
export class LiveService {
  private socket: WebSocket | null = null;
  private open = false;
  private failedOpens = 0;
  private everOpened = false;
  private gaveUp = false;
  private nextId = 1;
  private subs = new Map<number, LiveSub>();
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;

  constructor(private appMode: AppModeService) {}

  /** Whether subscriptions can be tried. A serverless or in-tab UI has no /ws. */
  get usable(): boolean {
    return !this.appMode.serverless && !this.gaveUp && typeof WebSocket !== 'undefined';
  }

  /**
   * Pushes the result of GET path now and whenever it changes, checking every
   * everyMs. Errors with LiveUnavailableError when the socket cannot be used.
   */
  subscribe(path: string, everyMs: number): Observable<LiveEvent> {
    return new Observable<LiveEvent>(subscriber => {
      if (!this.usable) {
        subscriber.error(new LiveUnavailableError());

        return undefined;
      }
      const id = this.nextId++;
      this.subs.set(id, { path: path, everyMs: everyMs, subscriber: subscriber });
      if (this.open) {
        this.sendSub(id);
      } else {
        this.connect();
      }

      return () => {
        this.subs.delete(id);
        if (this.open) {
          this.send({ type: 'unsub', id: id });
        }
      };
    });
  }

  /**
   * Follows GET /api/<url> like interval(everyMs).pipe(startWith(0)) would, but
   * pushed over the socket when it can be. Each emission is one result to
   * subscribe to: the parsed pushed body, or request() when polling. An error
   * status also goes through request(), so callers keep their HTTP error handling.
   */
  watch<T = any>(url: string, everyMs: number, request: () => Observable<T>, parse: (body: any) => T = b => b): Observable<Observable<T>> {
    const poll = timer(0, everyMs).pipe(map(() => request()));
    const path = '/api/' + url.replace(/^\/+/, '');

    return this.subscribe(path, everyMs).pipe(
      map(ev => {
        // The hypervisor caps subscriptions per socket; past it, poll.
        if (ev.status === 429) {
          throw new LiveUnavailableError();
        }
        if (ev.status < 200 || ev.status >= 300) {
          return request();
        }

        return defer(() => of(parse(decodeBody(ev.body))));
      }),
      catchError(err => err instanceof LiveUnavailableError ? poll : throwError(() => err)),
    );
  }

  private connect() {
    if (this.socket || this.reconnectTimer) {
      return;
    }
    const proto = location.protocol === 'https:' ? 'wss:' : 'ws:';
    const socket = new WebSocket(`${proto}//${location.host}/ws`);
    this.socket = socket;

    socket.onopen = () => {
      this.open = true;
      this.everOpened = true;
      this.failedOpens = 0;
      this.subs.forEach((_, id) => this.sendSub(id));
    };
    socket.onmessage = ev => {
      let frame: any;
      try {
        frame = JSON.parse(ev.data);
      } catch {
        return;
      }
      // A hypervisor without subscriptions answers a sub frame as a request it
      // cannot serve; give up so pages poll instead of waiting forever.
      if (frame.type === 'res' && this.subs.has(frame.id) && frame.status >= 400) {
        this.giveUp();

        return;
      }
      if (frame.type !== 'event') {
        return;
      }
      this.subs.get(frame.id)?.subscriber.next({ status: frame.status, body: frame.body });
    };
    socket.onclose = () => {
      const wasOpen = this.open;
      this.socket = null;
      this.open = false;
      if (!wasOpen) {
        this.failedOpens++;
      }
      if (!this.everOpened && this.failedOpens >= maxFailedOpens) {
        this.giveUp();

        return;
      }
      if (this.subs.size > 0) {
        this.reconnectTimer = setTimeout(() => {
          this.reconnectTimer = null;
          this.connect();
        }, Math.min(1000 * Math.pow(2, this.failedOpens), 30000));
      }
    };
  }

  private giveUp() {
    this.gaveUp = true;
    const subs = Array.from(this.subs.values());
    this.subs.clear();
    subs.forEach(s => s.subscriber.error(new LiveUnavailableError()));
  }

  private sendSub(id: number) {
    const sub = this.subs.get(id);
    if (sub) {
      this.send({ type: 'sub', id: id, path: sub.path, every_ms: sub.everyMs });
    }
  }

  private send(frame: any) {
    try {
      this.socket?.send(JSON.stringify(frame));
    } catch {
      // A send on a closing socket is retried by the resubscribe after reconnect.
    }
  }
}

// Bodies are JSON from the API's GET handlers; anything else is passed on as text.
function decodeBody(body: string): any {
  try {
    return JSON.parse(body);
  } catch {
    return body;
  }
}
